from build_pages import *
import csv
MEM='https://www.senalmemoria.co/articulos/observatorio-astronomico-colombia'
HIST=SPEC+'vol2num1-ciclo220-2.html'
PRE=SPEC+'vol2num1-ciclo220-1.html'
FIRST='https://raccefyn.co/index.php/raccefyn/article/view/3195'
GARDEN='https://raccefyn.co/index.php/raccefyn/article/view/3583'
CAT='https://biblioteca.accefyn.org.co/cgi-bin/koha/opac-detail.pl?biblionumber=36781'
pat='<figure><img class="wide-image" src="assets/historic.jpg" alt="Sede histórica del Observatorio Astronómico Nacional, de planta octagonal" loading="lazy"><figcaption>Sede histórica, centro de Bogotá. Imagen: Viasatelital. Consulta la procedencia en Fuentes y créditos.</figcaption></figure>'
pat+=section('origen','Una torre entre la botánica y el cielo','<p class="intro">La historia del Observatorio comienza en un mundo en el que medir el cielo era también una forma de conocer el territorio.</p><p>Su origen se vincula a José Celestino Mutis y a la Real Expedición Botánica. Los estudios históricos muestran una actividad astronómica y meteorológica anterior al edificio: los registros de Mutis, los trabajos de Francisco José de Caldas y sus intercambios con Alexander von Humboldt ayudan a reconstruir ese contexto.</p><p>El trabajo de Alberto Gómez Gutiérrez invita a leer esos antecedentes a través de documentos, diarios y correspondencia. La torre no surgió de una actividad aislada, sino de una red de prácticas científicas que relacionaba observación, viajes, geografía y colecciones.</p>'+source(PRE,'Alberto Gómez Gutiérrez: antecedentes del OAN')+'<p>Construida por fray Domingo de Petrés, la sede histórica se distingue por su planta octagonal. El archivo de Señal Memoria recupera una explicación de Benjamín Calvo sobre su arquitectura y reúne imágenes del edificio dentro del paisaje del centro de Bogotá.</p>'+source(MEM,'Señal Memoria: historia y archivo audiovisual'))
timeline=[('1802–1803','Se construye el Observatorio','La obra impulsada por Mutis comienza en mayo de 1802 y concluye el 20 de agosto de 1803, en el entorno de la Expedición Botánica.',HIST),('1804','Observar para medir el tiempo','Un estudio de documentos publicado en 2025 analiza registros solares, de declinación magnética y de satélites de Júpiter de abril a septiembre de 1804.',FIRST),('1805–1806','La etapa de Caldas','Caldas se establece en Santafé a finales de 1805 y desarrolla una actividad astronómica y meteorológica sostenida desde 1806.',PRE),('Siglo XIX','Ciencia e historia republicana','El edificio atraviesa interrupciones y cambios de uso. La trayectoria de Liévano, González Benito y Garavito muestra diferentes esfuerzos por fortalecer la práctica astronómica.',HIST),('1867 / 1936','El vínculo universitario','Las fuentes distinguen la incorporación a la Universidad Nacional en 1867 y su ratificación en 1936; conviene conservar esa diferencia al narrar la historia institucional.',MEM),('1952','Una sede en Ciudad Universitaria','Se construye el observatorio del campus, ampliando los espacios para la actividad académica y observacional.',MEM),('1975','Reconocimiento patrimonial','La sede histórica es declarada Monumento Nacional. Su conservación une la arquitectura con la memoria de la ciencia.',MEM),('1999','Formación de posgrado','La editorial institucional de 2023 sitúa en 1999 el inicio de la actividad docente e investigativa de sus posgrados.',SPEC+'oan220.html'),('2023','Nace eSPECTRA','El número inaugural acompaña la conmemoración de los 220 años y abre un espacio editorial para la comunidad.',SPEC+'oan220.html'),('2025','Se recupera el jardín','El proyecto con el Jardín Botánico de Bogotá renueva el entorno vegetal y su lectura patrimonial.',GARDEN)]
pat+='<section id="cronologia"><h2>Una historia en movimiento</h2><div class="timeline">'
for date,title,txt,url in timeline:
 pat+=f'<article><time>{date}</time><div><h3>{title}</h3><p>{txt}</p><p class="source-note">{link(url,"Documento de referencia")}</p></div></article>';SOURCES[url]=title
pat+='</div></section>'
pat+=section('instrumentos','Instrumentos: otras formas de leer el pasado','<p>Un instrumento conserva algo más que una técnica de observación: permite preguntar qué se medía, cómo se aprendía a usarlo, quién lo construyó y qué resultados produjo. Estudiar esa relación entre objetos y documentos es fundamental para comprender el patrimonio astronómico.</p><div class="two-col">'+card('Relojes y cronómetros','El análisis de las observaciones de 1804 identifica registros solares asociados, presumiblemente, a determinar el adelanto o atraso de un cronómetro y un reloj de péndulo. La medición del tiempo aparece así ligada a la observación del cielo.',FIRST,'Leer el estudio documental')+card('Telescopios y mediciones','El mismo estudio analiza observaciones de satélites de Júpiter dirigidas a precisar la longitud geográfica y mediciones de declinación magnética. Los documentos permiten reconstruir prácticas, incluso cuando la atribución de sus autores sigue en discusión.',FIRST,'Consultar la investigación')+'</div><p>Para investigar telescopios, relojes, brújulas, sextantes y otras familias de instrumentación histórica, la consulta debe contrastar inventarios, inscripciones, fotografías y registros de uso. Estos ejemplos orientan la investigación; no constituyen un inventario de piezas actualmente exhibidas.</p>'+source(GROUP+'patrimonio_observatorio_astronomico_nacional/','Grupo Patrimonio OAN')+'<p class="note">Esta web no sustituye un catálogo museológico. La identificación de una pieza, su fabricante, datación, procedencia y estado de conservación deben apoyarse en su ficha documental.</p>')
pat+=section('jardin','Un patrimonio que también está vivo','<p>La restauración del jardín, planeada en 2024 y realizada en 2025, es resultado de una alianza entre el OAN y el Jardín Botánico de Bogotá. El proyecto incorporó más de 1.400 individuos vegetales, incluidos seis nuevos árboles, y recuperó la dimensión simbólica del lugar.</p><p>El diseño vincula especies asociadas a la tradición botánica con la memoria de Mutis, Humboldt y Garavito. Es una forma de conectar astronomía, paisaje cultural y educación ambiental.</p>'+source(GARDEN,'Vargas Domínguez y colaboradores: restauración del jardín, 2026'))
archive=[('Catálogo documental · 1803–1930','Registro bibliográfico de la primera parte del catálogo del Archivo Histórico del OAN. Es un punto de partida para localizar la descripción de documentos y planear una consulta.',CAT,'Registro bibliográfico'),('Catálogo documental · 1930–1949','Referencia a la segunda parte, anunciada en 2010. Amplía el recorrido documental hacia la etapa de reorganización del Observatorio.','https://godues.wordpress.com/2010/06/04/catalogo-del-archivo-historico-del-oan-ed-rac-566/','Referencia de publicación'),('ConoSer · 25 de diciembre de 1998','Entrevista con Benjamín Calvo sobre los orígenes y la arquitectura. Referencia del archivo: BTCX30 017255.',MEM,'Archivo audiovisual'),('450 años de Bogotá · 1988','Pieza sobre legado, tradición y arte que incluye al Observatorio. Referencia del archivo: UMT-200471.',MEM,'Archivo audiovisual'),('Observatorio Astronómico Nacional · Foto 1','Registro de fotografía histórica conservado en la Biblioteca Virtual del Banco de la República.','https://babel.banrepcultural.org/digital/collection/p17054coll19/id/1194/','Archivo fotográfico'),('Humboldtiana neogranadina','Colección digital para explorar los viajes y los intercambios científicos de Humboldt. El tomo III aborda cartografía y astronomía.','https://bibliotecanacional.gov.co/es-co/colecciones/biblioteca-digital/humboldtiana/Documents/index.html','Biblioteca Nacional'),('Primeras observaciones · 1804','J. Gregorio Portilla revisa registros y propone una atribución distinta de las observaciones, mostrando cómo la historia cambia al releer las fuentes.',FIRST,'Investigación histórica'),('La Casa de la Botánica','Xavier Marquínez examina el contexto botánico, educativo y museal del lugar del que surgió el Observatorio.',SPEC+'vol2num1-ciclo220-3.html','Ensayo histórico')]
pat+='<section id="archivo"><h2>Puertas de entrada al archivo</h2><p>Documentos, registros y estudios para continuar investigando. Los materiales se consultan en las instituciones que los custodian.</p>'
for title,desc,url,kind in archive:
 pat+=f'<article class="resource"><div><span class="tag">{kind}</span></div><div><h3>{title}</h3><p>{desc}</p>{link(url,"Consultar recurso")}</div></article>';SOURCES[url]=title
pat+='</section>'
pat+=section('investigar','Cómo investigar el patrimonio','<div class="three-col">'+card('Localizar','Empieza por el catálogo y registra título, fecha, autor, fondo y signatura. Un registro bibliográfico no significa que el documento esté digitalizado.')+card('Contrastar','Distingue la fecha del documento de la del acontecimiento. Compara manuscritos, publicaciones y estudios antes de atribuir una observación o una pieza.')+card('Citar y conservar','Solicita las condiciones de consulta y reproducción al custodio. Conserva la procedencia de imágenes y transcripciones para que otros puedan verificarlas.')+'</div><p>El Grupo Patrimonio OAN trabaja por el patrimonio material e inmaterial. Para consultas sobre colecciones y proyectos, utiliza el contacto publicado en su ficha.</p><a class="button" href="mailto:patrimonioOAN@gmail.com">Consultar al Grupo Patrimonio ↗</a>')
page('patrimonio','El cielo también tiene memoria','HISTORIA Y PATRIMONIO','Un recorrido por la sede histórica, sus protagonistas, los instrumentos, el jardín y los documentos que permiten volver a contar su historia.',pat,[('origen','Orígenes'),('cronologia','Cronología'),('instrumentos','Instrumentos'),('jardin','El jardín'),('archivo','Archivo'),('investigar','Investigar')])

