labels={'prensa':'Prensa','audio':'Audio','video':'Video','articulo':'Artículo','archivo':'Archivo'}
med='<section><p class="intro">Voces, textos e imágenes que cuentan la investigación y la vida del Observatorio.</p><p>Una selección documentada de participaciones y recursos localizados en fuentes públicas. Incluye producción propia, entrevistas externas y archivo histórico; no representa un inventario exhaustivo de todas las apariciones.</p><label class="search-label" for="media-search">Buscar por persona, tema o medio</label><input id="media-search" class="search" type="search" placeholder="Por ejemplo: Calvo, telescopio, Cúmulo…"><div class="filter-bar" aria-label="Filtrar recursos por formato"><button data-filter="todos" aria-pressed="true">Todos</button>'+''.join(f'<button data-filter="{k}" aria-pressed="false">{v}</button>' for k,v in labels.items())+'</div><p id="media-count" role="status" aria-live="polite"></p><div class="empty">No se encontraron recursos con esos criterios. Prueba otra palabra o selecciona Todos.</div>'
for kind,publisher,date,title,desc,url in media:
 med+=f'<article class="resource" data-media="{kind}"><div><span class="tag">{labels[kind]}</span><small>{date}</small></div><div><small>{publisher}</small><h3>{title}</h3><p>{desc}</p>{link(url,"Consultar en la fuente")}</div></article>';SOURCES[url]=title+' — '+publisher
med+='</section><section class="inset"><h2>Más conversaciones, más miradas</h2><p>El canal del Observatorio conserva charlas y otros contenidos audiovisuales. Consulta su catálogo para seguir explorando.</p>'+link('https://www.youtube.com/channel/UCb1rF7m6wUC4Zhw-zsUWvLA','Canal de YouTube del OAN')+'<p class="source-note">Los videos y audios se abren en su plataforma original. Algunos sitios pueden requerir iniciar sesión, aceptar cookies o una suscripción. Las fechas no confirmadas se indican expresamente.</p></section>'
page('medios','Voces del Observatorio','MEDIATECA Y PRENSA','Entrevistas, reportajes, artículos y archivo para conocer la ciencia desde sus protagonistas.',med)

credits=section('criterios','Información con procedencia','<p>Portal elaborado a partir de fuentes institucionales del OAN y la Facultad de Ciencias, eSPECTRA, publicaciones científicas, archivos culturales y medios. Fecha de consulta: <strong>16 de septiembre de 2026</strong>.</p><p>Se presentan síntesis editoriales y enlaces para ampliar la lectura. El archivo de medios es una selección abierta a ampliación. Las fechas de los documentos y las de su publicación se distinguen cuando están disponibles.</p><p>Las fuentes pueden contener errores de plantilla, enlaces antiguos y diferencias históricas. No se trasladaron cupos de convocatorias sin contexto, fechas de eventos pasados como agenda actual ni textos ajenos al área. Los detalles operativos se remiten a los canales oficiales.</p>')
credits+=section('imagenes','Créditos de imágenes','<div class="table-scroll"><table><thead><tr><th>Imagen</th><th>Procedencia</th><th>Uso y atribución</th></tr></thead><tbody><tr><td>Sede histórica</td><td>'+link('https://viasatelital.com/mapas/bogota_observatorio_astronomico.php','Viasatelital')+'</td><td>Fotografía encontrada en esa página. No se localizó una licencia de reutilización expresa; validar autorización antes de la publicación institucional.</td></tr><tr><td>Cúpulas del campus</td><td>'+link(base+'asesorias_y_consultorias/nuestros_servicios/empresas/observatorio_astronomico_nacional/','Facultad de Ciencias, UNAL')+'</td><td>Fotografía institucional OAN-14. El portal indica algunos derechos reservados; confirmar el crédito y uso institucional.</td></tr><tr><td>Sol en ultravioleta</td><td>'+link('https://svs.gsfc.nasa.gov/14589/','NASA / SDO')+'</td><td>Observación del evento solar del 10–11 de mayo de 2024. Colores asociados a longitudes de onda ultravioleta; no es una imagen en tiempo real.</td></tr></tbody></table></div>')
credits+='<section id="fuentes"><h2>Fuentes consultadas y recursos</h2><ol class="linklist">'
for url,title in SOURCES.items():credits+='<li>'+link(url,e(title))+'</li>'
credits+='</ol></section>'
credits+=section('alcance','Alcance de esta propuesta','<p>Amigos del Observatorio se presenta como iniciativa en desarrollo. Los enlaces de contacto preparan mensajes en la aplicación de correo del visitante; no realizan inscripciones, reservas o pagos automáticos.</p><p>Los contenidos, la identidad visual y los datos deben pasar por revisión institucional antes de reemplazar el portal oficial. Esta versión no afirma aprobación ni representación administrativa.</p>')
page('fuentes','Fuentes y créditos','DOCUMENTACIÓN','Consulta la procedencia de la información, las imágenes y los recursos de este portal.',credits,[('criterios','Criterios'),('imagenes','Imágenes'),('fuentes','Bibliografía'),('alcance','Alcance')])
